#!/usr/bin/env python3
"""Materialize the reviewed Prompt 1 refactor payload deterministically."""
from __future__ import annotations
import base64
import gzip
from pathlib import Path

PAYLOAD = {'src/mfar_stage12.py': '', 'notebooks/01_AIS_Input_and_Cleaning.ipynb': '', 'notebooks/02_Time_Grid_and_State_Preparation.ipynb': '', 'tests/test_stage12_refactor.py': '', 'tools/apply_behavior_preserving_maintenance.py': '', 'tools/verify_prompt1_equivalence.py': '', 'docs/PROMPT_1_REFACTOR.md': ''}

def main() -> int:
    root = Path(__file__).resolve().parents[1]
    for relative, encoded in PAYLOAD.items():
        path = root / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(gzip.decompress(base64.b64decode(encoded)))
        print(path.relative_to(root))
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
